"614 :   private List<String> processArgs(String[] args) {
615 :     // Args4j has a different format that the old command-line parser.
616 :     // So we use some voodoo to get the args into the format that args4j
617 :     // expects.
618 :     Pattern argPattern = Pattern.compile("(--[a-zA-Z_]+)=(.*)");
619 :     Pattern quotesPattern = Pattern.compile("^['\"](.*)['\"]$");
620 :     List<String> processedArgs = Lists.newArrayList();
621 : 
622 :     for (String arg : args) {
623 :       Matcher matcher = argPattern.matcher(arg);
624 :       if (matcher.matches()) {
625 :         processedArgs.add(matcher.group(1));
626 : 
627 :         String value = matcher.group(2);
628 :         Matcher quotesMatcher = quotesPattern.matcher(value);
629 :         if (quotesMatcher.matches()) {
630 :           processedArgs.add(quotesMatcher.group(1));
631 :         } else {
632 :           processedArgs.add(value);
633 :         }
634 :       } else {
635 :         processedArgs.add(arg);
636 :       }
637 :     }
638 : 
639 :     return processedArgs;
640 :   }"

